def test_request_id_headers() -> None:
    def handler(request: httpx.Request) -> httpx.Response:
        status = 404 if request.url.path == "/missing" else 200
        return httpx.Response(status, headers={"x-vendor-id": "v-1", "x-request-id": "r-1"})

    vendor = sync_transport(handler, request_id_headers=("X-Vendor-Id",))
    assert vendor.request(Request("GET", "/ok")).request_id == "v-1"
    with pytest.raises(NotFoundError) as info:
        vendor.request(Request("GET", "/missing"))
    assert info.value.request_id == "v-1"
    default = sync_transport(handler)
    assert default.request(Request("GET", "/ok")).request_id == "r-1"
    headers = httpx.Headers({"x-vendor-id": "v-2", "x-request-id": "r-2"})
    assert error_from_status(400, "op", headers=headers).request_id == "r-2"
    assert (
        error_from_status(400, "op", headers=headers, request_id_headers=["x-vendor-id"]).request_id
        == "v-2"
    )
    assert "x-request-id" in REQUEST_ID_HEADERS


