def test_retry_after_from_headers() -> None:
    def now() -> float:
        return 2_000_000_000.0

    names = ("retry-after", "x-ratelimit-reset")
    assert RETRY_AFTER_HEADERS == ("retry-after",)
    assert retry_after_from_headers({"retry-after": "3"}, now=now) == 3.0
    assert retry_after_from_headers({"x-ratelimit-reset": "2"}) is None  # not a default name
    assert retry_after_from_headers({"x-ratelimit-reset": "2"}, names, now=now) == 2.0
    assert retry_after_from_headers({"x-ratelimit-reset": "2000000005"}, names, now=now) == 5.0
    assert retry_after_from_headers({"x-ratelimit-reset": "2000000005000"}, names, now=now) == 5.0
    assert retry_after_from_headers({"x-ratelimit-reset": "1999999990"}, names, now=now) == 0.0
    garbled = {"retry-after": "soon", "x-ratelimit-reset": "4"}
    assert retry_after_from_headers(garbled, names, now=now) == 4.0
    assert retry_after_from_headers({}, names, now=now) is None


def test_retry_after_headers_drive_the_retry_delay() -> None:
    errors: list[ErrorInfo] = []
    replies = [
        httpx.Response(429, headers={"x-ratelimit-reset": "0.05"}),
        httpx.Response(200, json={"ok": True}),
    ]

    def handler(request: httpx.Request) -> httpx.Response:
        return replies.pop(0)

    t = sync_transport(
        handler,
        retry_after_headers=("retry-after", "x-ratelimit-reset"),
        hooks=Hooks(on_error=errors.append),
    )
    started = time.monotonic()
    resp = t.request(Request("GET", "/x"))
    assert resp.attempts == 2
    assert time.monotonic() - started >= 0.05
    assert isinstance(errors[0].error, RateLimitError)
    assert errors[0].error.retry_after == 0.05


