def test_closed_sync_transport_raises_cancelled() -> None:
    t = sync_transport(lambda request: httpx.Response(200))
    t.close()
    with pytest.raises(CancelledError, match="client is closed"):
        t.request(Request("GET", "/x"))
    with pytest.raises(CancelledError, match="client is closed"):
        t.request(Request("GET", "/x"), cancel=CancelToken())


def test_close_aborts_an_inflight_cancellable_request() -> None:
    release = threading.Event()

    def handler(request: httpx.Request) -> httpx.Response:
        release.wait(5)
        return httpx.Response(200)

    t = sync_transport(handler)
    timer = threading.Timer(0.1, t.close)
    timer.start()
    started = time.monotonic()
    try:
        with pytest.raises(CancelledError, match="client is closed"):
            t.request(Request("GET", "/x"), cancel=CancelToken())
        assert time.monotonic() - started < 3
    finally:
        release.set()
        timer.join()


def test_cancel_token_still_wins_over_close() -> None:
    release = threading.Event()

    def handler(request: httpx.Request) -> httpx.Response:
        release.wait(5)
        return httpx.Response(200)

    t = sync_transport(handler)
    token = CancelToken()
    timer = threading.Timer(0.1, token.cancel)
    timer.start()
    try:
        with pytest.raises(CancelledError, match="op: cancelled"):
            t.request(Request("GET", "/x", operation="op"), cancel=token)
    finally:
        release.set()
        timer.join()
        t.close()


