@dataclasses.dataclass(frozen=True, repr=False)
class _Settings:
    url: str = "https://user:pw@svc.test/?token=abc"
    token_url: str = "https://user:pw@auth.test/oauth?client_secret=s3"
    otlp_endpoint: str = "https://collector.test/v1?api_key=k"
    secret_path: str = "kv/app"
    token_path: str = "/var/run/token"
    api_token: str = "raw-token"
    password: Secret = dataclasses.field(default_factory=lambda: Secret("hunter2"))
    timeout: float = 1.0


def test_safe_repr_url_and_path_fields() -> None:
    text = safe_repr(_Settings())
    assert "pw" not in text and "abc" not in text and "s3" not in text and "=k" not in text
    assert "token_url='https://[REDACTED]@auth.test/oauth?client_secret=[REDACTED]'" in text
    assert "otlp_endpoint='https://collector.test/v1?api_key=[REDACTED]'" in text
    assert "secret_path='kv/app'" in text
    assert "token_path='/var/run/token'" in text
    assert f"api_token={REDACTED!r}" in text
    assert "hunter2" not in text
    assert "timeout=1.0" in text


# --------------------------------------------------------------------------- polled steps


class _Eventually:
    """Lists a service only from the third call on; fails the first call."""

    def __init__(self) -> None:
        self.calls = 0

    def list(self) -> list[str]:
        self.calls += 1
        if self.calls == 1:
            raise RuntimeError("not ready")
        return ["a", "b", "late"] if self.calls >= 3 else ["a", "b"]


def _list(ctx: r.StepContext, args: dict[str, Any]) -> Any:
    return ctx.target.list()


r.register_ops("polledfake", {"list": _list, "once": _list}, polled={"list"})


def _scenario(op: str, **args: Any) -> dict[str, Any]:
    return {
        "id": f"polledfake.{op}",
        "category": "polledfake",
        "steps": [{"op": op, "args": args, "expect": {"contains": "late"}}],
    }


def test_polled_step_retries_until_the_expectation_passes() -> None:
    target = _Eventually()
    runner = r.ConformanceRunner({"polledfake": lambda ctx: target})
    result = runner.run_scenario(_scenario("list", intervalMs=10, timeoutMs=5000))
    assert result.status == "passed", result.reason
    assert target.calls == 3


def test_polled_step_reports_the_last_attempt_after_the_timeout() -> None:
    class Never:
        calls = 0

        def list(self) -> list[str]:
            self.calls += 1
            return ["a"]

    target = Never()
    runner = r.ConformanceRunner({"polledfake": lambda ctx: target})
    result = runner.run_scenario(_scenario("list", intervalMs=10, timeoutMs=60))
    assert result.status == "failed"
    assert "does not contain 'late'" in result.reason
    assert target.calls >= 2


def test_unpolled_step_runs_once() -> None:
    target = _Eventually()
    runner = r.ConformanceRunner({"polledfake": lambda ctx: target})
    result = runner.run_scenario(_scenario("once", intervalMs=10, timeoutMs=5000))
    assert result.status == "failed"
    assert target.calls == 1


