def test_async_runner_loop_still_closes() -> None:
    # A polled op whose handler is async still runs on the scenario's private loop.
    class AsyncTarget:
        def __init__(self) -> None:
            self.calls = 0

        async def list(self) -> list[str]:
            self.calls += 1
            await asyncio.sleep(0)
            return ["late"]

    target = AsyncTarget()
    runner = r.ConformanceRunner({"polledfake": lambda ctx: target})
    result = runner.run_scenario(_scenario("list", intervalMs=10, timeoutMs=1000))
    assert result.status == "passed", result.reason
    assert target.calls == 1
